parameters.text:
=Review the following patient prescription and return the structured clinical review.

Patient age: {{ $json.body.age }}
Gender: {{ $json.body.gender }}
Diagnosis: {{ $json.body.diagnosis }}
Current medications: {{ $json.body.medications }}
Known allergies: {{ $json.body.allergies }}
Kidney disease: {{ $json.body.kidneyDisease }}
Liver disease: {{ $json.body.liverDisease }}

parameters.jsCode:
const review = $json.output || {};
const issues = Array.isArray(review.issues) ? review.issues : [];
const body = $('Prescription Webhook').item.json.body || {};

let severe = 0, moderate = 0, low = 0;
for (const i of issues) {
  const sev = (i.severity || '').toLowerCase();
  if (sev === 'severe') severe++;
  else if (sev === 'moderate') moderate++;
  else if (sev === 'low') low++;
}

// Deterministic safety score (0-100): penalize by severity
let score = 100 - (severe * 30) - (moderate * 12) - (low * 4);
if (score < 0) score = 0;

let status;
if (severe > 0) status = 'High Risk';
else if (moderate > 0) status = 'Needs Review';
else status = 'Safe';

const highRiskPatient = severe > 0 || score < 50;

// Attach color codes for the frontend
const colorMap = { Low: 'green', Moderate: 'yellow', Severe: 'red' };
const issuesWithColor = issues.map(function (i) {
  return Object.assign({}, i, { color: colorMap[i.severity] || 'green' });
});

const reviewId = 'RX-' + $now.toFormat('yyyyLLdd') + '-' + Math.random().toString(36).slice(2, 8).toUpperCase();
const reviewedAt = $now.toISO();

const fullReview = {
  review_id: reviewId,
  reviewed_at: reviewedAt,
  patient: {
    age: body.age ?? null,
    gender: body.gender ?? null,
    diagnosis: body.diagnosis ?? null,
    medications: body.medications ?? null,
    allergies: body.allergies ?? null,
    kidneyDisease: body.kidneyDisease ?? null,
    liverDisease: body.liverDisease ?? null,
  },
  safety: {
    score: score,
    status: status,
    high_risk_patient: highRiskPatient,
    counts: { severe: severe, moderate: moderate, low: low },
  },
  issues: issuesWithColor,
  monitoring_recommendations: review.monitoring_recommendations || [],
  counseling_points: review.counseling_points || [],
  summary: review.summary || '',
  disclaimer: review.disclaimer ||
    'This review is AI-generated clinical decision support only. Final decisions belong to licensed healthcare professionals.',
};

return {
  json: {
    fullReview: fullReview,
    review_id: reviewId,
    reviewed_at: reviewedAt,
    patient_age: body.age ?? null,
    patient_gender: body.gender ?? null,
    diagnosis: body.diagnosis ?? null,
    medications: body.medications ?? null,
    allergies: body.allergies ?? null,
    kidney_disease: body.kidneyDisease === true,
    liver_disease: body.liverDisease === true,
    safety_score: score,
    safety_status: status,
    severe_count: severe,
    moderate_count: moderate,
    low_count: low,
    high_risk_patient: highRiskPatient,
    review_json: JSON.stringify(fullReview),
  },
};
